def closure(attrs, fds):
    res = set(attrs)
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            if lhs <= res and not rhs <= res:
                res |= rhs
                changed = True
    return res


def candidate_keys(all_attrs, fds):
    lst = sorted(all_attrs)
    n = len(lst)
    supers = []
    for mask in range(1, 1 << n):
        sub = frozenset(lst[i] for i in range(n) if mask >> i & 1)
        if closure(sub, fds) == set(all_attrs):
            supers.append(sub)
    cands = [s for s in supers if not any(o < s for o in supers)]
    return sorted(cands, key=lambda s: (len(s), ''.join(sorted(s))))


fds = [(frozenset('AB'), frozenset('C')),
       (frozenset('C'), frozenset('D')),
       (frozenset('D'), frozenset('A'))]
keys = candidate_keys({'A', 'B', 'C', 'D'}, fds)
print('候选键 =', [''.join(sorted(k)) for k in keys])

